const pruneParsedInstanceFromLogOutput = `-- name: PruneParsedInstanceFromLogOutput :exec
UPDATE
  river_job
SET
  metadata = jsonb_set(
    metadata,
    '{output,instances}',
    COALESCE(
      (
        SELECT
          jsonb_agg(elem)
        FROM
          jsonb_array_elements(COALESCE(metadata -> 'output' -> 'instances', '[]'::jsonb)) AS elem
        WHERE
          elem ->> 'id' <> $1::text
      ),
      '[]'::jsonb
    ),
    true
  )
WHERE
  args ->> 'log_group_id' = $2::text
  AND kind = 'log-parse'
`

